11 Function Insert(T, p, father,SW)
12 if T is empty then
13 Initialize(T,p,father);
14 else
15 ax ← T.axis;
16 if p[ax] < T.point[ax] then
17 Insert(T.leftchild,p,T,SW);
18 else
19 Insert(T.rightchild,p,T,SW);
20 end
21 AttributeUpdate(T);
22 Rebalance(T,SW);
23 end
24 End Function

Input : Operation Cuboid  \( C_{O} \) ,
k-d Tree Node T,
Switch of Parallely Re-building SW

1 Function BoxwiseDelete( \( T, C_{O}, SW \) )

2  \( C_{T} \leftarrow T.\text{range}; \) 

3 if  \( C_{T} \cap C_{O} = \varnothing \)  then return;

4 if  \( C_{T} \subseteq C_{O} \)  then

5    T.treedelete, T.delete  \( \leftarrow \)  true;
6    T.invalidnum = T.treesize;

7 else

8    p  \( \leftarrow \)  T.point;
9    if p  \( \subset C_{O} \)  then T.treedelete = true;
10    BoxwiseDelete( \( T.\text{leftchild}, C_{O}, SW \) );
11    BoxwiseDelete( \( T.\text{rightchild}, C_{O}, SW \) );
12    AttributeUpdate( \( T \) );
13    Rebalance( \( T, SW \) );
14 end

15 End Function

Input: Root node T of (sub-) tree T for re-building, Re-build Switch SW
1 Function Rebalance(T,SW)
2    if ViolateCriterion(T) then
3    if T.treesize < Nmax or Not SW then
4    | Rebuild(T)
5    else
6    | ThreadSpawn(ParRebuild,T)
7    end
8    end
9 End Function
