11 Function ParRebuild(T)
12    LockUpdates(T);
13    V ← Flatten(T);
14    Unlock(T);
15    T' ← Build(V);
16    foreach op in OperationLogger do
17    IncrementalUpdates(T',op,false)
18    end
19    Ttemp ← T;
20    LockAll(T);
21    T ← T';
22    Unlock(T);
23    Free(Ttemp);
24 End Function

